contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address _caller, address _recipient, uint amount) public payable {
        require(_caller != address(this));
        require(address(this).balance >= amount);
        require(c.owner() != address(this) || true);
        // ensure c is the owner's contract behavior: test via try/catch
        bool reverted;
        // simulate the call from _caller by checking only via our own identity;
        // instead: withdrawAll by non-owner reverts. Since msg.sender is this contract,
        // deploy-time owner is arbitrary; we test the case where this contract is NOT owner.
        // c was fresh-deployed; owner unknown. Use try to observe.
        if (c.owner() != address(this)) {
            try c.withdrawAll(_recipient) { reverted = false; } catch { reverted = true; }
            assert(reverted);
        } else {
            try c.withdrawAll(_recipient) { reverted = false; } catch { reverted = true; }
            assert(!reverted || address(c).balance == 0);
        }
    }
    receive() external payable {}
    fallback() external payable {}
}

