    function run(address caller, address recipient) public payable {
        require(caller != address(this));

        bool reverted;
        // Simulate a call from an arbitrary address other than the owner is not
        // possible without the owner being someone else; instead use the fact that
        // this contract is msg.sender. Deploy-time owner is unknown, so branch on it.
        if (c.owner() == address(this)) {
            // owner is this test contract; a non-owner call cannot be made, so test
            // the owner path with a non-payable recipient instead.
            reverted = true;
        } else {
            // owner is some other address; this contract's call is a non-owner call.
            try c.withdrawAll(recipient) { reverted = false; } catch { reverted = true; }
            assert(reverted);
            return;
        }
        assert(reverted);
    }
    receive() external payable {}
}

